int main() {
    using namespace std::chrono_literals;
    const std::chrono::milliseconds timeout = 250ms;
    const std::chrono::seconds heartbeat = 30s;
    const std::chrono::minutes cooldown = 5min;

    const std::chrono::milliseconds total = timeout + heartbeat + cooldown;
    std::cout << "total: " << total.count() << " ms\n";
    std::cout << "heartbeats per cooldown: " << cooldown / heartbeat << '\n';
    std::cout << "timeouts per heartbeat: " << heartbeat / timeout << '\n';
    std::cout << "cooldown in seconds: " << std::chrono::seconds(cooldown).count() << '\n';

    const std::chrono::seconds whole = std::chrono::duration_cast<std::chrono::seconds>(total);
    std::cout << "total in whole seconds: " << whole.count() << '\n';
    const std::chrono::duration<double> exact = total;
    std::cout << "exact: " << exact.count() << " s\n";
    return 0;
}

