int main() {
    using namespace std::chrono_literals;
    const std::chrono::seconds max_age = 2s;
    // A fixed "now": 1'700'000'000 seconds after 1970, instead of Clock::now().
    const Clock::time_point now{1'700'000'000s};
    const std::vector<Clock::time_point> quoted = {now - 500ms, now - 2s, now - 3500ms};

    for (std::size_t i = 0; i < quoted.size(); ++i) {
        const Clock::duration age = now - quoted[i];
        const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(age);
        const bool stale = age > max_age;
        std::cout << "quote " << i + 1 << ": " << ms.count() << " ms old, " << (stale ? "stale" : "fresh") << '\n';
    }
    return 0;
}

