// Prints nanoseconds since midnight as HH:MM:SS.nnnnnnnnn.
void print_clock(std::chrono::nanoseconds ts) {
    const auto h = std::chrono::duration_cast<std::chrono::hours>(ts);
    ts -= h;
    const auto m = std::chrono::duration_cast<std::chrono::minutes>(ts);
    ts -= m;
    const auto s = std::chrono::duration_cast<std::chrono::seconds>(ts);
    ts -= s;
    std::cout << std::setfill('0') << std::setw(2) << h.count() << ':' << std::setw(2) << m.count()
              << ':' << std::setw(2) << s.count() << '.' << std::setw(9) << ts.count();
}

int main() {
    // ts_ns values as a feed sends them: nanoseconds since midnight.
    const std::vector<int64_t> ts_ns = {34'200'000'000'125, 34'200'000'412'000, 57'599'999'999'999};
    for (int64_t raw : ts_ns) {
        print_clock(std::chrono::nanoseconds{raw});
        std::cout << '\n';
    }
    const std::chrono::nanoseconds gap{ts_ns[1] - ts_ns[0]};
    const std::chrono::duration<double, std::micro> gap_us = gap;
    std::cout << "gap: " << gap.count() << " ns = " << gap_us.count() << " us\n";
    return 0;
}

