#include <chrono>
#include <cstddef>
#include <cstdint>
#include <ctime>
#include <iomanip>
#include <iostream>
#include <vector>

using Clock = std::chrono::system_clock;
using Days = std::chrono::duration<int64_t, std::ratio<86400>>;  // C++20 has std::chrono::days

// Prints a time point as a date and time in UTC, with put_time's format codes.
void print_utc(Clock::time_point t, const char* format) {
    const std::time_t secs = Clock::to_time_t(t);
    const std::tm parts = *std::gmtime(&secs);
    std::cout << std::put_time(&parts, format);
}

// NYSE trades 09:30 to 16:00 New York time, Monday to Friday.
bool nyse_open(Clock::time_point local) {
    const std::time_t secs = Clock::to_time_t(local);
    const std::tm parts = *std::gmtime(&secs);
    if (parts.tm_wday == 0 || parts.tm_wday == 6) {  // Sunday or Saturday
        return false;
    }
    using namespace std::chrono_literals;
    const auto since_midnight = local - std::chrono::floor<Days>(local);
    return since_midnight >= 9h + 30min && since_midnight < 16h;
}

int main() {
    using namespace std::chrono_literals;
    const std::vector<int64_t> utc_secs = {1705416300, 1705414500, 1709559900, 1710164700, 1721161800, 1705158000};
    // New York's offset from UTC on each date: -5 h in winter (EST), -4 h in summer (EDT).
    const std::vector<int> offset_hours = {-5, -5, -5, -4, -4, -5};
    for (std::size_t i = 0; i < utc_secs.size(); ++i) {
        const Clock::time_point utc{std::chrono::seconds{utc_secs[i]}};
        const Clock::time_point local = utc + std::chrono::hours{offset_hours[i]};
        print_utc(utc, "%a %Y-%m-%d %H:%M UTC = ");
        print_utc(local, "%H:%M New York, ");
        std::cout << (nyse_open(local) ? "open" : "closed") << '\n';
    }
    return 0;
}

